import{I as n,o as l,c as r,b6 as a,J as p,w as h,j as t,a as i}from"./chunks/framework.COUcLbTA.js";const g=JSON.parse('{"title":"Double Diamond: First Do the Right Thing, Then Do It Right","description":"A beginner-friendly introduction to the Double Diamond. Understand Discover, Define, Develop, and Deliver so you do not rush into prototypes before the real problem is clear.","frontmatter":{"title":"Double Diamond: First Do the Right Thing, Then Do It Right","description":"A beginner-friendly introduction to the Double Diamond. Understand Discover, Define, Develop, and Deliver so you do not rush into prototypes before the real problem is clear."},"headers":[],"relativePath":"en/stage-1/appendix-double-diamond/index.md","filePath":"en/stage-1/appendix-double-diamond/index.md"}'),d={name:"en/stage-1/appendix-double-diamond/index.md"},b=Object.assign(d,{setup(u){const o="About <strong>1.5 hours</strong>";return(c,e)=>{const s=n("ChapterIntroduction");return l(),r("div",null,[e[1]||(e[1]=a('<h1 id="double-diamond-first-do-the-right-thing-then-do-it-right" tabindex="-1">Double Diamond: First Do the Right Thing, Then Do It Right <a class="header-anchor" href="#double-diamond-first-do-the-right-thing-then-do-it-right" aria-label="Permalink to “Double Diamond: First Do the Right Thing, Then Do It Right”">​</a></h1><p><a id="top-dd"></a></p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2>',3)),p(s,{duration:o,tags:["Double Diamond","Design Thinking","Demand Analysis","Solution Design"],coreOutput:"1 clearer problem definition and 1 more reasonable validation entry point",expectedOutput:"Stop rushing straight into prototypes and learn to think through the problem before comparing solutions"},{default:h(()=>[...e[0]||(e[0]=[t("p",null,'One of the most common beginner mistakes in product work is not "not trying hard enough." It is moving into solutions too fast.',-1),t("p",null,"The moment an idea appears, people start thinking about screens, buttons, AI integrations, login flows, and prototype tools. Then after a lot of work, they realize the most basic question was never clear: does the user really have this pain point, and is it worth solving now? What feels like project progress is sometimes just accelerating very quickly in the wrong direction.",-1),t("p",null,[i("That is exactly what the "),t("strong",null,"Double Diamond"),i(" is designed to prevent.")],-1),t("p",null,[i("Its most valuable reminder is this: "),t("strong",null,'"choosing the right thing to do" and "doing the thing right" are two different stages.'),i(" If the problem is still unclear and you rush into prototyping, you usually just make the wrong direction more complete.")],-1)])]),_:1}),e[2]||(e[2]=a(`<div class="info custom-block"><p class="custom-block-title">Minimal SOP</p><p><strong>Goal</strong>: After this, you should be much clearer about when to think about the problem first and when to start designing solutions and prototypes.</p><p><strong>Action</strong>: Move through <code>Discover → Define → Develop → Deliver</code>, and only do the kind of work that belongs to the current stage.</p><p><strong>Result</strong>: You will leave with a clearer problem definition, several comparable solution directions, and one testable first version.</p><p><strong>Quick links</strong>: <a href="#dd-what">What the Double Diamond is</a> · <a href="#dd-first">The first diamond</a> · <a href="#dd-ai">How AI can help</a></p></div><h2 id="what-you-will-learn" tabindex="-1">What You Will Learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to “What You Will Learn”">​</a></h2><ol><li>What the Double Diamond is, and why it is especially useful for beginners</li><li>What Discover, Define, Develop, and Deliver actually mean</li><li>How to tell whether you should still be expanding or whether it is time to narrow down</li><li>How to use the Double Diamond in AI products, prototype design, and demand validation</li></ol><p><a id="dd-what"></a></p><h2 id="_1-what-the-double-diamond-really-is" tabindex="-1"><a href="#top-dd">1. What the Double Diamond Really Is</a> <a class="header-anchor" href="#_1-what-the-double-diamond-really-is" aria-label="Permalink to “1. What the Double Diamond Really Is”">​</a></h2><p>The Double Diamond is a classic design process framework promoted by the UK <strong>Design Council</strong>. It represents a full design and innovation process as two connected diamond shapes.</p><p>It is called a &quot;diamond&quot; because each diamond contains two opposite but equally important motions:</p><ul><li><strong>diverge</strong>: open the view and look at more possibilities</li><li><strong>converge</strong>: narrow the scope and make choices</li></ul><p>The full process has four steps:</p><ol><li><strong>Discover</strong>: broadly understand users, problems, context, and market</li><li><strong>Define</strong>: extract the core problem that is actually worth solving</li><li><strong>Develop</strong>: explore multiple solution directions around that problem</li><li><strong>Deliver</strong>: choose, prototype, test, and deliver the more suitable solution</li></ol><p>If you want the shortest way to remember it:</p><ul><li><strong>the first diamond</strong>: first figure out what problem is really worth solving</li><li><strong>the second diamond</strong>: then decide what kind of solution should solve it</li></ul><p>That is why a very accurate summary is:</p><ul><li><strong>first diamond: choose the right thing to do</strong></li><li><strong>second diamond: do that thing right</strong></li></ul><h2 id="_2-why-the-double-diamond-is-especially-useful-for-beginners" tabindex="-1">2. Why the Double Diamond Is Especially Useful for Beginners <a class="header-anchor" href="#_2-why-the-double-diamond-is-especially-useful-for-beginners" aria-label="Permalink to “2. Why the Double Diamond Is Especially Useful for Beginners”">​</a></h2><p>The most common beginner rhythm looks like this:</p><ul><li>get an idea</li><li>feel that the direction sounds exciting</li><li>start prototyping immediately</li><li>keep adding more features</li><li>eventually lose track of the actual problem</li></ul><p>The value of the Double Diamond is not that it makes the process more complicated. It <strong>forces you to separate &quot;understanding the problem&quot; from &quot;designing the solution.&quot;</strong></p><p>That sounds obvious, but it matters a lot. Many failed products were not badly executed. They failed because:</p><ul><li>they chose the wrong problem</li><li>they misunderstood the user</li><li>they locked in a solution too early</li><li>they spent a lot of time polishing detail before validating direction</li></ul><p>The Double Diamond keeps reminding you:</p><ul><li>do not assume a problem is real just because the idea is easy to imagine</li><li>do not assume something is worth building just because it is technically buildable</li><li>do not assume a prototype matters just because it looks complete</li></ul><p><a id="dd-first"></a></p><h2 id="_3-the-first-diamond-choose-the-right-thing-to-do" tabindex="-1"><a href="#top-dd">3. The First Diamond: Choose the Right Thing to Do</a> <a class="header-anchor" href="#_3-the-first-diamond-choose-the-right-thing-to-do" aria-label="Permalink to “3. The First Diamond: Choose the Right Thing to Do”">​</a></h2><p>The first diamond is about the <strong>problem itself</strong>, not the solution.</p><p>You can translate it into one simple sentence:</p><p><strong>before building, first make sure this is worth building at all.</strong></p><h3 id="_3-1-discover-open-up-the-problem-space-first" tabindex="-1">3.1 Discover: Open up the problem space first <a class="header-anchor" href="#_3-1-discover-open-up-the-problem-space-first" aria-label="Permalink to “3.1 Discover: Open up the problem space first”">​</a></h3><p>The core task in Discover is <strong>broad research, not quick conclusions.</strong></p><p>Typical work in this phase includes:</p><ul><li>watching how users behave in real situations</li><li>interviewing potential users and asking when the problem last happened</li><li>seeing how they currently patch the issue together</li><li>checking how competitors and substitutes handle it</li><li>collecting context about market, workflow, constraints, and surrounding systems</li></ul><p>Many people think Discover just means &quot;read more things.&quot; But the more important part is this: <strong>you need to understand people and situations, not just collect information.</strong></p><p>For example, imagine you want to build an AI tool for organizing meeting notes. In Discover, the better questions are:</p><ul><li>what exactly feels painful after a meeting</li><li>is the hard part recording, organizing, or syncing</li><li>are people writing notes themselves, asking interns to do it, listening to recordings later, or simply skipping documentation</li><li>which meeting types really need notes, and which ones do not</li></ul><p>The main goal in Discover is not to get the answer right away. It is to <strong>avoid assuming too early that you already know the answer.</strong></p><h3 id="_3-2-define-extract-the-core-problem-from-a-pile-of-information" tabindex="-1">3.2 Define: Extract the core problem from a pile of information <a class="header-anchor" href="#_3-2-define-extract-the-core-problem-from-a-pile-of-information" aria-label="Permalink to “3.2 Define: Extract the core problem from a pile of information”">​</a></h3><p>If Discover opens the view, Define starts to narrow it.</p><p>Define is not about preserving every observation. It is about asking:</p><ul><li>which problem is most worth solving first</li><li>which problem shows up most often, hurts most, or matters most</li><li>which single situation version one should focus on</li></ul><p>The core of this phase is turning a broad topic into one clear problem definition.</p><p>For example, maybe you start with:</p><blockquote><p>I want to build an AI tool that improves meeting efficiency.</p></blockquote><p>By the time you reach Define, a much stronger version might be:</p><blockquote><p>We will first solve the problem that project teams often cannot produce a shareable meeting note with action items, owners, and deadlines within 10 minutes after a 30-60 minute collaboration meeting.</p></blockquote><p>At that point, the problem is starting to become clear:</p><ul><li>who the users are</li><li>what the situation is</li><li>where the bottleneck is</li><li>what success would look like</li></ul><p>The essence of Define is this: <strong>go from &quot;there are many problems&quot; to &quot;this is the one problem we will solve first.&quot;</strong></p><h2 id="_4-the-second-diamond-do-the-thing-right" tabindex="-1">4. The Second Diamond: Do the Thing Right <a class="header-anchor" href="#_4-the-second-diamond-do-the-thing-right" aria-label="Permalink to “4. The Second Diamond: Do the Thing Right”">​</a></h2><p>Only after you complete the first diamond does it make sense to move fully into the second. By then, you are not solving a vague direction anymore. You are solving a specific problem that has already been narrowed down.</p><h3 id="_4-1-develop-explore-multiple-solutions-around-the-same-problem" tabindex="-1">4.1 Develop: Explore multiple solutions around the same problem <a class="header-anchor" href="#_4-1-develop-explore-multiple-solutions-around-the-same-problem" aria-label="Permalink to “4.1 Develop: Explore multiple solutions around the same problem”">​</a></h3><p>The focus in Develop is <strong>to expand the solution space around one defined problem.</strong></p><p>This kind of divergence is different from Discover:</p><ul><li>Discover expands the problem space</li><li>Develop expands the solution space</li></ul><p>Still using the meeting-note example, in Develop you can ask:</p><ul><li>should this be a web tool or a meeting plugin</li><li>should it process recordings after the meeting or work in real time</li><li>should it focus only on summary, or mainly on extracting action items</li><li>should it optimize for personal productivity or team sync</li><li>should the user edit freely, or should the product output a structured template directly</li></ul><p>This is a good phase for brainstorming, comparison, and co-creation.</p><p>But there is an important precondition: <strong>all of these solution directions must still serve the same defined problem.</strong><br> If the problem is not clear, Develop quickly turns back into random feature sprawl.</p><h3 id="_4-2-deliver-choose-prototype-test-and-put-the-solution-into-reality" tabindex="-1">4.2 Deliver: Choose, prototype, test, and put the solution into reality <a class="header-anchor" href="#_4-2-deliver-choose-prototype-test-and-put-the-solution-into-reality" aria-label="Permalink to “4.2 Deliver: Choose, prototype, test, and put the solution into reality”">​</a></h3><p>Deliver is the convergence phase inside the second diamond.</p><p>At this stage, you are no longer trying to imagine more possibilities. You are making choices:</p><ul><li>which direction fits the current stage best</li><li>which version is smallest but still useful</li><li>which features are necessary first and which can wait</li><li>how to prototype, test, and validate with a smaller group</li></ul><p>Many people think Deliver means &quot;launch.&quot; A more accurate way to understand it is this:</p><p><strong>turn one solution into something testable, usable, and improvable.</strong></p><p>That could be:</p><ul><li>a low-fidelity flow diagram</li><li>a Figma prototype</li><li>a working MVP</li><li>a small user test</li><li>a revised version after one round of feedback</li></ul><p>The point of Deliver is not perfection. It is to <strong>get the solution into a real environment quickly enough to validate it.</strong></p><h2 id="_5-a-comparison-table-that-is-easy-to-remember" tabindex="-1">5. A Comparison Table That Is Easy to Remember <a class="header-anchor" href="#_5-a-comparison-table-that-is-easy-to-remember" aria-label="Permalink to “5. A Comparison Table That Is Easy to Remember”">​</a></h2><p>If you keep mixing up the four stages, this table is the easiest version to remember:</p><table tabindex="0"><thead><tr><th>Stage</th><th>What you are doing</th><th>Keywords</th><th>Common outputs</th></tr></thead><tbody><tr><td>Discover</td><td>Understanding the problem</td><td>research, observation, interviews, collecting information</td><td>user insight, context notes, problem list</td></tr><tr><td>Define</td><td>Defining the problem</td><td>synthesis, focus, tradeoff, rewriting the problem</td><td>problem statement, priority, MVP cut</td></tr><tr><td>Develop</td><td>Exploring solutions</td><td>brainstorming, comparison, co-creation, prototype directions</td><td>solution list, flow sketches, prototype directions</td></tr><tr><td>Deliver</td><td>Validating solutions</td><td>prototype, test, iteration, delivery</td><td>prototype, test feedback, improved version</td></tr></tbody></table><p>You can compress it even further:</p><ul><li><strong>Discover / Define</strong>: choose the right thing to do</li><li><strong>Develop / Deliver</strong>: do that thing right</li></ul><h2 id="_6-common-double-diamond-mistakes" tabindex="-1">6. Common Double Diamond Mistakes <a class="header-anchor" href="#_6-common-double-diamond-mistakes" aria-label="Permalink to “6. Common Double Diamond Mistakes”">​</a></h2><h3 id="_6-1-jumping-into-deliver-before-doing-discover" tabindex="-1">6.1 Jumping into Deliver before doing Discover <a class="header-anchor" href="#_6-1-jumping-into-deliver-before-doing-discover" aria-label="Permalink to “6.1 Jumping into Deliver before doing Discover”">​</a></h3><p>This is the most common one. People get an idea and immediately start drawing screens, writing PRDs, integrating models, or building pages.</p><p>The problem is not that they are not serious. The problem is that they may not even know whether the problem is worth solving.</p><h3 id="_6-2-staying-in-discover-for-too-long-and-never-reaching-define" tabindex="-1">6.2 Staying in Discover for too long and never reaching Define <a class="header-anchor" href="#_6-2-staying-in-discover-for-too-long-and-never-reaching-define" aria-label="Permalink to “6.2 Staying in Discover for too long and never reaching Define”">​</a></h3><p>The opposite mistake is endless research, endless reading, endless interviews, and no convergence.</p><p>The Double Diamond is not telling you to expand forever. It is reminding you that after expansion, you must eventually make choices.</p><h3 id="_6-3-quietly-changing-the-problem-after-define" tabindex="-1">6.3 Quietly changing the problem after Define <a class="header-anchor" href="#_6-3-quietly-changing-the-problem-after-define" aria-label="Permalink to “6.3 Quietly changing the problem after Define”">​</a></h3><p>Some teams define a problem, but during Develop they discover that a certain solution is easier to build. Then they quietly rewrite the problem so it fits their preferred solution.</p><p>That is dangerous. At that point, you may no longer be solving the real problem. You may be defending a favorite implementation.</p><h3 id="_6-4-treating-deliver-as-build-everything" tabindex="-1">6.4 Treating Deliver as &quot;build everything&quot; <a class="header-anchor" href="#_6-4-treating-deliver-as-build-everything" aria-label="Permalink to “6.4 Treating Deliver as &quot;build everything&quot;”">​</a></h3><p>Deliver does not mean shipping a huge complete product. Often, a testable prototype or one round of real user testing is already a strong deliverable.</p><h2 id="_7-how-to-use-the-double-diamond-in-ai-products" tabindex="-1">7. How to Use the Double Diamond in AI Products <a class="header-anchor" href="#_7-how-to-use-the-double-diamond-in-ai-products" aria-label="Permalink to “7. How to Use the Double Diamond in AI Products”">​</a></h2><p>AI products are especially likely to fall into capability-first thinking because model capabilities are so tempting. It is very easy to jump straight to:</p><ul><li>should we add multimodal input</li><li>should we build an agent</li><li>should we connect workflow automation</li><li>should we add voice, image, or web search</li></ul><p>The Double Diamond forces you to ask first:</p><ul><li>where are users actually stuck</li><li>is this bottleneck something AI is truly needed for</li><li>without AI, what is so weak about the current method</li><li>if AI is added, what real progress does it create</li></ul><p>That helps you avoid a very common failure mode:</p><p><strong>high capability, low value.</strong></p><p>A practical sequence looks like this:</p><ol><li>in Discover, observe how users currently handle the task</li><li>in Define, write the most painful scenario as one clear problem statement</li><li>in Develop, compare which AI capabilities best serve that problem</li><li>in Deliver, build a small first version and test it with real users</li></ol><h2 id="_8-a-double-diamond-template-you-can-reuse" tabindex="-1">8. A Double Diamond Template You Can Reuse <a class="header-anchor" href="#_8-a-double-diamond-template-you-can-reuse" aria-label="Permalink to “8. A Double Diamond Template You Can Reuse”">​</a></h2><p>If you are working on your own product, you can write through the stages in this order:</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>Who are the users I am observing?</li><li>When did they last experience this problem?</li><li>How do they solve it now?</li><li>What feels most annoying, slow, or risky?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>Out of all these problems, which one is most worth solving first?</li><li>Which situation is most frequent or most important?</li><li>Who exactly does version one serve, and what exactly does it solve?</li><li>If we solve it well, what change happens in the user&#39;s state?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>What solution directions are possible for this problem?</li><li>Which directions are lightest, fastest, and easiest to validate?</li><li>Which parts are essential now, and which can wait?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>What is the smallest thing we can deliver to validate this direction?</li><li>Is it a flow sketch, a prototype, or an MVP?</li><li>Who do we need to test with?</li><li>After testing, how will we decide whether to continue, change, or stop?</li></ul><h2 id="_9-a-full-example-a-beginner-can-understand" tabindex="-1">9. A Full Example a Beginner Can Understand <a class="header-anchor" href="#_9-a-full-example-a-beginner-can-understand" aria-label="Permalink to “9. A Full Example a Beginner Can Understand”">​</a></h2><p>Suppose you want to build an AI tool that helps college students prepare job-application resumes.</p><p>Many people would immediately jump into the second diamond and start asking:</p><ul><li>should there be one-click beautification</li><li>should there be smart rewriting</li><li>should it auto-match the job description</li><li>should it generate self-introductions</li></ul><p>But with the Double Diamond, a stronger process looks like this:</p><h3 id="first-diamond" tabindex="-1">First diamond <a class="header-anchor" href="#first-diamond" aria-label="Permalink to “First diamond”">​</a></h3><p><strong>Discover</strong></p><ul><li>talk to recent graduates about the last time they revised a resume</li><li>watch how they turn an old version into a new one</li><li>figure out whether their biggest issue is &quot;I cannot write,&quot; &quot;I cannot revise,&quot; or &quot;I cannot judge quality&quot;</li></ul><p><strong>Define</strong></p><ul><li>narrow it into a more specific problem</li><li>not &quot;students cannot make resumes&quot;</li><li>but &quot;students applying for internships for the first time struggle to rewrite existing experiences into role-fit wording, so they delay applying&quot;</li></ul><h3 id="second-diamond" tabindex="-1">Second diamond <a class="header-anchor" href="#second-diamond" aria-label="Permalink to “Second diamond”">​</a></h3><p><strong>Develop</strong></p><ul><li>compare several directions: template library, AI rewriting, role comparison, resume scoring, example references</li></ul><p><strong>Deliver</strong></p><ul><li>build only one narrow first version, such as &quot;rewrite resume bullet points based on a job description&quot;</li><li>let five students test it and see whether it helps them submit a first version faster</li></ul><p>Once the first diamond is solid, the second diamond becomes much clearer.</p><h2 id="_10-summary" tabindex="-1">10. Summary <a class="header-anchor" href="#_10-summary" aria-label="Permalink to “10. Summary”">​</a></h2><p>The strongest part of the Double Diamond is that it breaks one big messy process into four clearer moves:</p><ul><li>first expand to understand the problem</li><li>then narrow to define the problem</li><li>then expand to explore solutions</li><li>finally narrow to deliver the solution</li></ul><p>It does not make you slower. It helps you <strong>avoid many detours that look busy but are moving in the wrong direction.</strong></p><p>This matters even more in the AI era because building things is getting easier and faster. When &quot;making something&quot; becomes cheap, the scarcer skill becomes this: <strong>are you solving a problem worth solving, and are you solving it in an appropriate way?</strong></p><p>If you remember only one sentence, remember this:</p><p><strong>first choose the right thing to do, then do that thing right.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-how-ai-can-help-you-run-the-double-diamond" tabindex="-1"><a href="#top-dd">11. How AI Can Help You Run the Double Diamond</a> <a class="header-anchor" href="#_11-how-ai-can-help-you-run-the-double-diamond" aria-label="Permalink to “11. How AI Can Help You Run the Double Diamond”">​</a></h2><p>The Double Diamond is not an AI tool, but AI works very well as an accelerator inside all four stages. The key is not to let AI decide for you. The key is to let it help you expand the view, organize information, compare directions, and generate validation material.</p><h3 id="_11-1-in-discover-use-ai-to-build-a-rough-problem-map-first" tabindex="-1">11.1 In Discover, use AI to build a rough problem map first <a class="header-anchor" href="#_11-1-in-discover-use-ai-to-build-a-rough-problem-map-first" aria-label="Permalink to “11.1 In Discover, use AI to build a rough problem map first”">​</a></h3><p>Before formal interviews and deeper research, AI can help you do a lightweight scan of the space, for example:</p><ul><li>what common substitutes already exist</li><li>what users complain about most in public communities</li><li>which scenarios and user groups this problem shows up in</li><li>what current products often ignore</li></ul><p>This cannot replace real research, but it is very useful for creating a first map of the space.</p><p>A simple beginner prompt could be:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to build a tool that helps college students improve resumes.</span></span>
<span class="line"><span>Do not help me think about features yet.</span></span>
<span class="line"><span>First help me figure out what problems people most often run into here.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Initial problem map:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. They do not know what experiences to include</span></span>
<span class="line"><span>2. They do not know how to tailor the resume to different roles</span></span>
<span class="line"><span>3. They revise many times and still do not know if it is good enough</span></span>
<span class="line"><span>4. They need someone else to review it, but cannot always ask</span></span>
<span class="line"><span>5. Because they feel unsure, they keep delaying applications</span></span></code></pre></div><p>That kind of output is not there to replace your judgment. It helps you enter Discover faster.</p><h3 id="_11-2-in-define-use-ai-to-narrow-the-problem-statement" tabindex="-1">11.2 In Define, use AI to narrow the problem statement <a class="header-anchor" href="#_11-2-in-define-use-ai-to-narrow-the-problem-statement" aria-label="Permalink to “11.2 In Define, use AI to narrow the problem statement”">​</a></h3><p>After collecting a lot of information, one of the hardest things is turning it into one really clear problem statement. You can give research notes to AI and ask it to compress them into candidate definitions:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Below are user notes and research notes I collected during Discover:</span></span>
<span class="line"><span>[paste the content]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please do 3 things:</span></span>
<span class="line"><span>1. summarize the most common problem patterns</span></span>
<span class="line"><span>2. based on frequency, pain, and ease of validation, suggest 3 problems worth prioritizing</span></span>
<span class="line"><span>3. write each problem as one clear problem statement</span></span></code></pre></div><p>You can keep the input very simple too:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>These are the issues I collected:</span></span>
<span class="line"><span>1. people do not know what to write on the resume</span></span>
<span class="line"><span>2. people do not know how to revise it</span></span>
<span class="line"><span>3. people keep feeling it is not good enough, so they do not apply</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please help me decide which problem is the best first one to solve.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Recommended first problem:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;Students applying for internships for the first time are unsure whether their resume has reached a submit-ready level, so they keep revising and delay applying.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reasons:</span></span>
<span class="line"><span>1. it is more concrete</span></span>
<span class="line"><span>2. it explains the delay behavior</span></span>
<span class="line"><span>3. it is easier to test with a smaller first version</span></span></code></pre></div><p>That is useful because it helps you narrow a fuzzy set of issues into something closer to an MVP starting point.</p><h3 id="_11-3-in-develop-use-ai-to-expand-multiple-solution-directions" tabindex="-1">11.3 In Develop, use AI to expand multiple solution directions <a class="header-anchor" href="#_11-3-in-develop-use-ai-to-expand-multiple-solution-directions" aria-label="Permalink to “11.3 In Develop, use AI to expand multiple solution directions”">​</a></h3><p>Once people define a problem, they often fixate immediately on the first solution that comes to mind. AI is very useful here as a forced divergence tool:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I have defined this core problem: [your problem statement]</span></span>
<span class="line"><span>Please do not give me only one final answer.</span></span>
<span class="line"><span>Instead, propose 2-3 solution directions from each of these angles:</span></span>
<span class="line"><span>1. the lightest MVP</span></span>
<span class="line"><span>2. the best option for validating demand</span></span>
<span class="line"><span>3. the best option for improving user experience</span></span>
<span class="line"><span>4. a non-AI solution</span></span>
<span class="line"><span>5. an AI-based solution</span></span>
<span class="line"><span></span></span>
<span class="line"><span>At the end, compare the strengths, risks, and validation cost of each direction.</span></span></code></pre></div><p>That stops you from getting trapped by one favorite solution too early.</p><p>A simpler prompt could be:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>My problem statement is:</span></span>
<span class="line"><span>&quot;Students delay applying because they are not sure whether their resume is ready.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please suggest 4 different solution directions, not just one.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Option 1: resume readiness checklist</span></span>
<span class="line"><span>Option 2: job-description-based rewrite assistant</span></span>
<span class="line"><span>Option 3: resume risk detector</span></span>
<span class="line"><span>Option 4: example comparison library</span></span></code></pre></div><p>Now you are in comparison mode instead of only staring at one AI rewriting path.</p><h3 id="_11-4-in-deliver-use-ai-to-generate-prototype-copy-and-testing-material" tabindex="-1">11.4 In Deliver, use AI to generate prototype copy and testing material <a class="header-anchor" href="#_11-4-in-deliver-use-ai-to-generate-prototype-copy-and-testing-material" aria-label="Permalink to “11.4 In Deliver, use AI to generate prototype copy and testing material”">​</a></h3><p>Once you reach Deliver, AI is very useful for speeding up work like:</p><ul><li>writing copy for low-fidelity prototypes</li><li>organizing user test scripts</li><li>generating multiple versions of titles, buttons, and instructions</li><li>summarizing test feedback and issue lists</li></ul><p>For example, you can ask AI to generate a 20-minute user test script, or summarize five pieces of feedback into a decision frame like &quot;continue / revise / pause.&quot;</p><p>A very small input could be:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I made a very simple prototype:</span></span>
<span class="line"><span>the user uploads a resume, and the system tells them which parts are not yet ready for submission.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please generate a 15-minute user testing script.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15-minute user testing script:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Ask the user to describe their most recent resume submission experience</span></span>
<span class="line"><span>2. Let them upload a resume independently</span></span>
<span class="line"><span>3. Observe whether they understand the feedback</span></span>
<span class="line"><span>4. Ask which parts feel helpful and which parts feel confusing</span></span>
<span class="line"><span>5. Ask whether they would want to use this again before the next application</span></span></code></pre></div><p>That is useful because it moves you from &quot;I finished the prototype&quot; to &quot;how do I actually test this?&quot;</p><h3 id="_11-5-let-ai-act-as-a-stage-guard" tabindex="-1">11.5 Let AI act as a stage guard <a class="header-anchor" href="#_11-5-let-ai-act-as-a-stage-guard" aria-label="Permalink to “11.5 Let AI act as a stage guard”">​</a></h3><p>One of the biggest risks in the Double Diamond is that people skip stages. You can directly ask AI to act like a process guard:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please act as a product process coach.</span></span>
<span class="line"><span>Here is my current project state: [your description]</span></span>
<span class="line"><span>Please judge whether I am mainly in Discover, Define, Develop, or Deliver.</span></span>
<span class="line"><span>Then tell me:</span></span>
<span class="line"><span>1. whether I am jumping ahead too early</span></span>
<span class="line"><span>2. what the most important action in the current stage is</span></span>
<span class="line"><span>3. what I should not do yet</span></span></code></pre></div><p>That is especially helpful for beginners because it is very easy to start prototyping before the problem is truly clear.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to “Assignments”">​</a></h2><ol><li>Pick one product idea you have been thinking about and write a draft for its Discover, Define, Develop, and Deliver stages</li><li>In Define, force yourself to compress the problem into one concrete sentence</li><li>In Develop, list at least 3 different solution directions instead of clinging to the first one</li><li>In Deliver, write down one smallest validation version you could ship within a week</li></ol><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><p>This article mainly draws on the Design Council&#39;s official material about the Double Diamond. These are good places to continue:</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,172))])}}});export{g as __pageData,b as default};
